(()=>{
'use strict';
const host=document.getElementById('workbench'),intro=host?.querySelector('.page-intro'),shell=host?.querySelector('.flight-shell'),foot=host?.querySelector('.flight-foot');
if(!intro||!shell||!foot)return;
const mapArea=host.querySelector('.flight-map-area'),timeline=document.createElement('section');timeline.className='map-timeline';
for(const selector of ['.timeline-heading','.flight-play','#flight-phase','.flight-tip']){const node=host.querySelector(selector);if(node)timeline.append(node)}
mapArea.append(timeline);
const chooser=document.createElement('div');chooser.className='mode-chooser';chooser.innerHTML='<div class="mode-label-row"><span class="mode-select-label"></span><span class="mode-select-hint"></span></div><div class="mode-tabs" role="group"></div>';intro.after(chooser);
const coming=document.createElement('section');coming.className='mode-coming';coming.hidden=true;coming.setAttribute('aria-live','polite');coming.innerHTML='<div class="overline">SIMULATION MODE</div><h2></h2><p></p><button type="button"></button>';shell.after(coming);
const badge=intro.querySelector('.status'),description=intro.querySelector('p'),tabs=chooser.querySelector('.mode-tabs'),keys=['cargo','passenger','mixed','emergency'];let mode='cargo';
const copy={zh:{label:'选择模拟模式',hint:'请选择一个模式',cargo:'货运多机规划仿真',passenger:'客运多机规划仿真',mixed:'客货混运规划仿真',emergency:'应急物资配送仿真',available:'已开放',pending:'开发中',cargoDesc:'设置多组任务，观察航线、时空避让与同步飞行；载重等货运约束尚未模拟。',pendingDesc:'该模式正在开发，敬请期待。',cargoBadge:'货运演示',pendingBadge:'开发中',pendingTitle:'该模拟模式正在开发中',pendingText:'功能尚未开放。可切换回货运模式，继续使用已创建的任务。',back:'返回货运模拟'},en:{label:'Simulation mode',hint:'Choose a mode',cargo:'Cargo flight planning',passenger:'Passenger flight planning',mixed:'Passenger & cargo planning',emergency:'Emergency supply delivery',available:'Available',pending:'In development',cargoDesc:'Explore coordinated routes and synchronized flight. Cargo constraints such as payload are not yet modeled.',pendingDesc:'This mode is in development.',cargoBadge:'Cargo demo',pendingBadge:'In development',pendingTitle:'Simulation mode in development',pendingText:'This mode is not available yet. Return to cargo mode to continue with your existing missions.',back:'Return to cargo simulation'}};
function lang(){return document.documentElement.lang.startsWith('en')?'en':'zh'}
function selectMode(next){const play=document.getElementById('flight-play');if(next!=='cargo'&&play&&(play.textContent==='暂停'||play.textContent==='Pause'))play.click();mode=next;render()}
function render(){const t=copy[lang()],isCargo=mode==='cargo';chooser.querySelector('.mode-select-label').textContent=t.label;chooser.querySelector('.mode-select-hint').textContent=t.hint;tabs.setAttribute('aria-label',t.label);tabs.replaceChildren(...keys.map(key=>{let button=document.createElement('button'),name=document.createElement('strong'),state=document.createElement('small');button.type='button';button.className='mode-tab'+(key===mode?' active':'');button.setAttribute('aria-pressed',String(key===mode));name.textContent=t[key];state.textContent=key==='cargo'?t.available:t.pending;button.append(name,state);button.addEventListener('click',()=>selectMode(key));return button}));description.textContent=isCargo?t.cargoDesc:t.pendingDesc;badge.textContent=isCargo?t.cargoBadge:t.pendingBadge;shell.hidden=!isCargo;foot.hidden=!isCargo;coming.hidden=isCargo;coming.querySelector('h2').textContent=t.pendingTitle;coming.querySelector('p').textContent=t.pendingText;coming.querySelector('button').textContent=t.back}
coming.querySelector('button').addEventListener('click',()=>{selectMode('cargo');tabs.querySelector('button').focus()});document.getElementById('language').addEventListener('click',render);render();
})();

